import sys, pathlib; sys.path.insert(0, str(pathlib.Path(__file__).parent))
from synlib import *
E = []
S = lambda ch, a, b=None: C("snell", ch, a, b)
B = lambda ch, a, b=None: C("berkowitz", ch, a, b)
EMG = lambda txt: pathol("Nerve conduction and EMG", "EMG/NCS", txt, sequence="n/a")
X = dict(tier="extended")

E.append(syn("syn-callosal-disconnection", "Callosal disconnection syndrome", "vascular", ["corpus-callosum", "gyrus-angular", "cortex-premotor-sma"], "bilateral",
 "After surgical division of the corpus callosum for epilepsy, or an infarct or tumor of its body, a right-handed patient can name objects placed in the right hand but not in the left, cannot write with the left hand or copy a drawing with the right, and the left hand may button what the right hand unbuttons. Reading in the left visual field is impossible. In daily life the deficits are subtle and are found only when each hemisphere is tested alone.",
 [D("cognitive", "n/a", "left hand and left hemispace", "Left-hand tactile anomia and left-hand agraphia; left ideomotor apraxia to verbal command", "corpus-callosum"), D("cognitive", "n/a", "right hand", "Right-hand constructional apraxia (right hemisphere skills unavailable to the left hand's controller)", "corpus-callosum"), D("visual-field", "contralateral", "left hemifield", "Left hemialexia: words in the left field cannot be read", "pathway-visual"), D("other", "n/a", "both hands", "Intermanual conflict, alien hand phenomena and diagonistic dyspraxia after anterior callosal lesions", "cortex-premotor-sma")],
 "Sensation and motor control are crossed: the left hand reports to the right hemisphere and the left visual field projects to the right occipital cortex, whereas language lives in the left hemisphere. In an intact brain the corpus callosum transfers information between the hemispheres in milliseconds, so what the right hemisphere feels or sees can be named. When the callosum is divided, the right hemisphere still perceives the object in the left hand and can select it by touch from a tray, but the name cannot reach the left hemisphere's speech areas; the left hand cannot write because the right hemisphere has no access to the left hemisphere's language, and it cannot carry out a verbal command because the praxis programs of the left parietal lobe cannot cross to the right motor cortex. The right hand, controlled by the left hemisphere, loses the visuospatial skill of the right parietal lobe, hence its constructional apraxia. Words in the left visual field reach only the right occipital lobe and cannot cross the splenium to the left angular gyrus, a left hemialexia that is the mirror of alexia without agraphia. Anterior callosal lesions disconnect the supplementary motor areas and produce conflict between the hands. Each hemisphere is intact, so ordinary behavior, which uses both eyes and both hands, is nearly normal, and the syndrome reveals itself only when input is lateralized.",
 [pathol("Callosal infarct", "MRI", "Restricted diffusion in the body or splenium of the corpus callosum, from anterior or posterior cerebral artery pericallosal branch occlusion.", sequence="DWI"), pathol("Callosotomy", "MRI", "Surgical division of the anterior two-thirds or the whole callosum on sagittal T1.", sequence="T1"), pathol("Callosal tumor or demyelination", "MRI", "'Butterfly' glioblastoma crossing the callosum, or the callososeptal lesions of multiple sclerosis; Marchiafava–Bignami necrosis in alcoholism.", sequence="FLAIR")],
 ["Callosotomy for epilepsy", "Pericallosal artery infarct", "Glioblastoma or lymphoma of the callosum", "Marchiafava–Bignami disease", "Multiple sclerosis", "Callosal agenesis (mostly compensated)"],
 [("Left parietal apraxia", "Bilateral apraxia; naming intact in both hands"), ("Left hemineglect", "Left field and hand ignored rather than unnamed; awareness deficit"), ("Corticobasal degeneration", "Progressive asymmetric rigidity, dystonia and alien limb with cortical sensory loss")],
 ["Test each hand and each visual field separately when a callosal lesion is suspected", "Treat the underlying lesion; callosotomy deficits are mild and adapt", "Occupational therapy strategies using bimanual and verbal cues"],
 [S(8, 289, 290), B(19, 191)], marker=structs("corpus-callosum"), imagingHint=hint("sagittal", 0, -10, 20, "body and splenium of the corpus callosum"), preset="medial-l", eponyms=["split-brain syndrome"], **X))

E.append(syn("syn-raymond", "Raymond syndrome (ventral pontine abducens)", "vascular", ["level-pons-caudal", "abducens-nucleus", "pontine-nuclei", "artery-basilar"], "ipsilateral",
 "A patient has an isolated inability to abduct one eye with horizontal diplopia, and a hemiparesis of the arm and leg on the opposite side, without facial weakness. The crossed pattern of a sixth nerve palsy and contralateral hemiplegia places the lesion in the ventral caudal pons where the abducens fascicle crosses the corticospinal bundles, medial to the site of the Millard–Gubler lesion.",
 [D("cranial-nerve", "ipsilateral", "lateral rectus", "Abducens palsy: abduction deficit with esotropia", "cn-06-abducens"), D("motor", "contralateral", "arm and leg", "Hemiparesis with upper motor neuron signs", "pathway-lateral-corticospinal"), D("cranial-nerve", "n/a", "face spared", "No facial palsy (distinguishes it from Millard–Gubler)", "facial-motor-nucleus")],
 "The abducens nerve fascicle leaves its nucleus in the dorsal pontine tegmentum and runs ventrally and slightly caudally through the paramedian basis pontis to emerge at the pontomedullary sulcus; on its way it passes between the corticospinal bundles descending in the basis pontis. A small paramedian ventral lesion cuts the fascicle, which is the final uncrossed motor pathway to the ipsilateral lateral rectus, together with the corticospinal fibers, which have not yet crossed and will decussate in the medulla to serve the contralateral limbs, producing the classical alternating pattern. The facial nerve fascicle emerges more laterally, so a strictly paramedian lesion spares the face, whereas a slightly more lateral lesion adds the facial palsy of the Millard–Gubler syndrome; a lesion extending dorsally to the abducens nucleus converts the palsy into a conjugate gaze palsy (Foville). The corticobulbar fibers to the lower face travel with the corticospinal tract, so a mild contralateral central facial weakness may occur, but a complete ipsilateral peripheral facial palsy is absent by definition. The syndrome is rare in pure form and is usually a paramedian pontine infarct from basilar perforator disease.",
 [pathol("Paramedian ventral pontine infarct", "MRI", "Small restricted diffusion focus in the paramedian caudal basis pontis on the side of the abducens palsy.", sequence="DWI"), pathol("Pontine hemorrhage or cavernoma", "MRI", "Hemorrhagic lesion in the ventral caudal pons on SWI.", sequence="SWI")],
 ["Basilar perforator infarct", "Pontine hemorrhage", "Cavernoma", "Demyelination", "Pontine glioma"],
 [("Millard–Gubler syndrome", "Adds an ipsilateral peripheral facial palsy"), ("Foville syndrome", "Conjugate gaze palsy instead of a single sixth nerve palsy"), ("Sixth nerve palsy with a coincidental capsular stroke", "Two lesions; hemiparesis would include the face")],
 ["Acute stroke pathway", "Occlusion for diplopia; abducens palsies from small infarcts usually recover", "MRI with contrast in younger patients to exclude demyelination or cavernoma"],
 [B(9, 78)], level="pons-caudal", arteryId="artery-basilar", marker=sphere(-4, -32, -33, 6), imagingHint=hint("axial", -4, -32, -33, "paramedian caudal basis pontis"), preset="anterior", eponyms=["Raymond syndrome"], **X))

E.append(syn("syn-pontine-hemorrhage", "Pontine hemorrhage", "vascular", ["level-pons-caudal", "level-pons-rostral", "reticular-formation", "pontine-nuclei", "arteries-pontine"], "bilateral",
 "A hypertensive patient collapses and within minutes is deeply comatose with pinpoint pupils that still react to a bright light under magnification, quadriplegia with bilateral extensor plantars, absent horizontal eye movements even with head turning and caloric stimulation, ocular bobbing, a high fever and irregular breathing. Small hemorrhages confined to the tegmentum or the base produce instead a survivable lateral pontine or pure motor picture.",
 [D("consciousness", "bilateral", "pontine reticular formation", "Abrupt coma within minutes", "reticular-formation"), D("pupil", "bilateral", "both pupils", "Pinpoint but reactive pupils from bilateral interruption of the descending sympathetic fibers with intact parasympathetic outflow", "pathway-oculosympathetic"), D("motor", "bilateral", "all limbs", "Quadriplegia with bilateral extensor plantars; decerebrate posturing", "pathway-lateral-corticospinal"), D("oculomotor", "bilateral", "horizontal", "Absent horizontal eye movements not overcome by oculocephalic or caloric stimulation; ocular bobbing", "pathway-horizontal-gaze"), D("autonomic", "bilateral", "thermoregulation and breathing", "Hyperthermia and abnormal respiratory patterns", "reticular-formation")],
 "The paramedian perforating branches of the basilar artery are small end arteries that develop lipohyalinosis and microaneurysms under chronic hypertension, and their rupture floods the center of the pons, usually at the junction of the base and tegmentum, from where the hematoma spreads across the midline and often into the fourth ventricle. Because the pons is compact, a single hematoma destroys bilateral structures at once. The corticospinal fibers of both sides, uncrossed at this level, are cut, so all four limbs are paralyzed; the pontine reticular formation that maintains arousal is destroyed, so coma is immediate; both abducens nuclei, both paramedian pontine reticular formations and both MLFs are involved, so no horizontal eye movement can be produced by any pathway, whereas vertical movements generated in the spared midbrain persist and, released, produce the bobbing. The descending sympathetic fibers pass through the tegmentum bilaterally and are interrupted while the midbrain parasympathetic outflow is intact, hence pinpoint pupils that react, a combination that separates a pontine lesion from opioid poisoning only by the accompanying signs. Hyperthermia reflects the loss of descending control over the hypothalamic set point. A hematoma confined to one side of the tegmentum produces instead an ipsilateral gaze palsy, facial palsy and contralateral sensory loss, and a small basal hematoma a pure motor hemiparesis, both with a far better outlook.",
 [pathol("Pontine hemorrhage", "CT", "Hyperdense hematoma in the center of the pons, often extending into the fourth ventricle, with hydrocephalus; large hematomas over 5 mL or extending across the midline carry a poor prognosis.", sequence="CT non-contrast"), pathol("Cavernoma or arteriovenous malformation", "MRI", "'Popcorn' lesion with a hemosiderin rim, or flow voids, in younger patients without hypertension.", sequence="SWI")],
 ["Hypertensive rupture of paramedian basilar perforators", "Cavernous malformation", "Arteriovenous malformation", "Anticoagulation", "Hemorrhagic transformation of a pontine infarct"],
 [("Opioid overdose", "Pinpoint pupils with coma but preserved eye movements and normal tone; responds to naloxone"), ("Basilar artery occlusion", "Similar deficits but evolution over hours with prodromal symptoms; no blood on CT"), ("Central pontine myelinolysis", "Subacute after sodium correction; T2 change without hemorrhage")],
 ["Airway protection and blood pressure control; reverse anticoagulation", "Ventricular drainage for hydrocephalus; surgical evacuation is rarely beneficial", "Prognosis depends on hematoma volume and level of consciousness at presentation; discuss goals of care early"],
 [B(9, 78, 79), B(19, 187)], level="pons-rostral", arteryId="artery-basilar", marker=sphere(0, -30, -28, 12), imagingHint=hint("axial", 0, -30, -28, "central pons at the basis–tegmentum junction"), preset="anterior", **X))

E.append(syn("syn-ramsay-hunt", "Ramsay Hunt syndrome (herpes zoster oticus)", "infectious", ["cn-07-facial", "ganglion-geniculate", "cn-08-vestibulocochlear"], "ipsilateral",
 "A patient develops severe pain in and around one ear, followed within days by a complete facial palsy on that side and a crop of vesicles in the ear canal, on the eardrum or on the soft palate. Taste is lost on the front of the tongue and sounds are painfully loud. Many also have vertigo, tinnitus and hearing loss because the eighth nerve is inflamed alongside. Recovery is slower and less complete than in Bell palsy, and the pain may persist as postherpetic neuralgia.",
 [D("cranial-nerve", "ipsilateral", "whole face", "Lower motor neuron facial palsy, usually severe, with hyperacusis and loss of taste", "cn-07-facial"), D("pain", "ipsilateral", "ear, auricle, deep ear", "Severe otalgia preceding the rash; postherpetic neuralgia after", "ganglion-geniculate"), D("sensory-light-touch", "ipsilateral", "external auditory canal, concha, tympanic membrane", "Vesicular eruption in the sensory territory of the facial nerve (and palate)", "ganglion-geniculate"), D("vestibular", "ipsilateral", "eighth nerve", "Vertigo, nystagmus, sensorineural hearing loss and tinnitus", "cn-08-vestibulocochlear")],
 "Varicella zoster virus that has lain dormant in the geniculate ganglion since childhood chickenpox reactivates and inflames the ganglion and the facial nerve within the narrow bony facial canal, where swelling compresses the nerve and blocks conduction. The facial nerve is the uncrossed lower motor neuron supply of the ipsilateral face, so the palsy is complete on that side including the forehead, and because the inflammation is at or proximal to the geniculate ganglion, the branches that leave distal to it are all affected: the greater petrosal nerve (reduced tearing), the nerve to the stapedius (hyperacusis) and the chorda tympani (loss of taste on the anterior two-thirds of the tongue). The geniculate ganglion also holds the cell bodies of the small cutaneous sensory territory of the facial nerve, the concha, the external auditory canal and the tympanic membrane, and of the taste and general sensory fibers to the palate, so the vesicles appear in exactly these places, which are the diagnostic clue. The vestibulocochlear nerve shares the internal acoustic meatus and is often involved by the spreading inflammation, adding vertigo and deafness, and less often the fifth, ninth and tenth nerves are affected. The virus damages axons more than the presumed viral inflammation of Bell palsy, hence the worse prognosis.",
 [pathol("Facial nerve and geniculate ganglion inflammation", "MRI", "Enhancement of the facial nerve in the labyrinthine segment and geniculate ganglion, often extending to the eighth nerve and the membranous labyrinth, on post-contrast T1 of the temporal bone.", sequence="T1+Gd"), pathol("Zoster ganglionitis", "LP/CSF", "Mild lymphocytic pleocytosis with VZV DNA on PCR when the diagnosis is uncertain or the brainstem is involved.", sequence="n/a")],
 ["Reactivation of varicella zoster virus in the geniculate ganglion", "Immunosuppression, age, HIV"],
 [("Bell palsy", "No vesicles, less pain, no eighth nerve involvement; zoster sine herpete can mimic it and is diagnosed by PCR or serology"), ("Otitis externa or media with facial palsy", "Purulent discharge, drum changes, no vesicles"), ("Lyme facial palsy", "Tick exposure, erythema migrans, often bilateral")],
 ["Look in the ear and at the palate of every patient with a facial palsy and ear pain", "Antiviral (valacyclovir) plus prednisolone within 72 hours; eye protection", "Audiology and vestibular assessment; analgesia for neuralgia"],
 [B(13, 122, 124)], marker=nerve("cn-07-facial-l"), imagingHint=hint("axial", -35, -30, -30, "facial nerve at the geniculate ganglion in the temporal bone"), preset="inferior", eponyms=["herpes zoster oticus", "geniculate zoster"], **X))

E.append(syn("syn-superior-orbital-fissure", "Superior orbital fissure and orbital apex syndromes", "compressive", ["cn-03-oculomotor", "cn-04-trochlear", "cn-06-abducens", "cn-05-trigeminal", "cn-02-optic", "artery-ophthalmic"], "ipsilateral",
 "After a facial fracture, or with a tumor or inflammation at the back of the orbit, a patient has a fixed, drooping eye that cannot move in any direction, a dilated pupil, numbness of the forehead and upper eyelid and loss of the corneal reflex, with a bulging, congested eye. If vision in that eye is also lost with an afferent pupillary defect, the lesion has extended medially to the optic canal: the orbital apex syndrome.",
 [D("oculomotor", "ipsilateral", "III, IV and VI", "Complete external ophthalmoplegia with ptosis", "cn-03-oculomotor"), D("pupil", "ipsilateral", "one pupil", "Dilated, fixed pupil (parasympathetic fibers in III) and loss of accommodation", "pathway-pupillary-light-reflex"), D("sensory-light-touch", "ipsilateral", "forehead, upper lid, cornea, nose (V1)", "Anesthesia in the ophthalmic division with an absent corneal reflex", "cn-05-trigeminal"), D("other", "ipsilateral", "orbit", "Proptosis and chemosis from superior ophthalmic vein obstruction", "sinus-cavernous"), D("visual-acuity", "ipsilateral", "one eye (orbital apex)", "Visual loss with a relative afferent pupillary defect when the optic canal is involved", "cn-02-optic")],
 "The superior orbital fissure is the gap between the greater and lesser wings of the sphenoid through which the oculomotor, trochlear and abducens nerves, the three branches of the ophthalmic division of the trigeminal nerve (lacrimal, frontal and nasociliary) and the superior ophthalmic vein pass between the cavernous sinus and the orbit. All of these are uncrossed structures serving the ipsilateral eye, so a lesion at the fissure paralyzes all the ocular muscles and the levator, dilates the pupil because the parasympathetic fibers travel in the third nerve, and removes sensation from the forehead, upper lid, cornea and bridge of the nose, with venous congestion from obstruction of the ophthalmic vein. The optic nerve and the ophthalmic artery enter the orbit separately through the optic canal, medial to the fissure, so vision is spared in a pure fissure syndrome; a process that extends to involve the canal, as at the orbital apex where the fissure and canal converge, adds an optic neuropathy with visual loss and an afferent pupillary defect. The distinction from the cavernous sinus syndrome, which involves the same nerves a centimeter further back, rests on the maxillary division (V2) and the sympathetic plexus, which run through the sinus but not the fissure, so a Horner or cheek numbness points to the sinus.",
 [pathol("Fracture of the sphenoid wing", "CT", "Fracture line through the superior orbital fissure or optic canal with bone fragments and orbital hematoma on thin-section CT of the orbit.", sequence="CT non-contrast"), pathol("Orbital apex lesion", "MRI", "Enhancing mass or inflammation at the apex (meningioma, lymphoma, metastasis, invasive fungal sinusitis, IgG4 disease, Tolosa–Hunt) extending through the fissure, with optic nerve involvement; fat-suppressed post-contrast coronal images.", sequence="T1+Gd"), pathol("Thyroid eye disease (mimic)", "CT", "Enlarged extraocular muscle bellies crowding the apex and compressing the optic nerve.", sequence="CT contrast")],
 ["Craniofacial trauma with sphenoid fracture", "Sphenoid wing meningioma", "Metastasis, lymphoma, nasopharyngeal carcinoma", "Invasive fungal sinusitis, orbital cellulitis", "Tolosa–Hunt and IgG4-related inflammation", "Herpes zoster ophthalmicus"],
 [("Cavernous sinus syndrome", "Adds V2 sensory loss and a Horner syndrome; involves the carotid"), ("Orbital cellulitis", "Fever, painful proptosis, cranial nerves initially spared"), ("Ocular myasthenia", "Painless, variable, no sensory loss or proptosis")],
 ["Urgent thin-section CT of the orbits for trauma; MRI with contrast for non-traumatic cases", "Optic canal decompression or high-dose steroids when vision is threatened; antifungal therapy and debridement for mucormycosis", "Corneal protection for the anesthetic, non-blinking eye"],
 [S(11, 324), S(11, 337), S(11, 354)], marker=sphere(-25, 25, -15, 10), imagingHint=hint("coronal", -25, 25, -15, "orbital apex and superior orbital fissure"), preset="anterior", eponyms=["Rochon-Duvigneaud syndrome"], **X))

E.append(syn("syn-accessory-palsy", "Spinal accessory nerve palsy", "traumatic", ["cn-11-accessory", "nucleus-ambiguus"], "ipsilateral",
 "Weeks after a lymph node biopsy in the posterior triangle of the neck, a patient complains of a dull ache in the shoulder, difficulty lifting the arm above the head and a shoulder that hangs lower than the other. The upper trapezius is wasted, the scapula sits low and rotated with lateral winging that increases on abducting the arm, and shrugging is weak; turning the head against resistance is normal because the sternocleidomastoid branch left the nerve higher up.",
 [D("motor", "ipsilateral", "trapezius", "Shoulder droop, weak shrug, weak abduction above 90°, lateral scapular winging on abduction", "cn-11-accessory"), D("motor", "ipsilateral", "sternocleidomastoid (proximal lesions only)", "Weak head turning to the opposite side and flexion; spared in posterior triangle lesions", "cn-11-accessory"), D("pain", "ipsilateral", "shoulder and neck", "Aching from traction on the unsupported shoulder girdle and stretched ligaments", "cn-11-accessory")],
 "The spinal root of the accessory nerve arises from the upper five cervical segments, ascends through the foramen magnum, leaves the skull through the jugular foramen and descends in the neck, first supplying the sternocleidomastoid and then crossing the posterior triangle superficially, beneath only skin and platysma, to reach the trapezius. That exposed course is where surgeons find and injure it during lymph node biopsy, neck dissection or carotid surgery. The nerve is the uncrossed motor supply of the ipsilateral trapezius and sternocleidomastoid, so the deficit is on the side of the injury: without the trapezius the shoulder is not held up and the scapula cannot be rotated upward to allow full abduction, so the arm cannot be raised above the horizontal, and the scapula drifts downward and laterally with its lateral border winging when the arm is abducted, a pattern that differs from the medial winging on forward pushing of a long thoracic nerve palsy. Whether the sternocleidomastoid is spared tells the level: it is weak with lesions at the jugular foramen or upper neck, spared with the common posterior triangle lesions. Cortical control of the sternocleidomastoid is ipsilateral and of the trapezius contralateral, a curiosity that explains the head deviation of hemispheric seizures.",
 [EMG("Denervation of the trapezius with a preserved sternocleidomastoid in posterior triangle lesions, or of both muscles in jugular foramen lesions; normal serratus anterior."), pathol("Jugular foramen lesion", "MRI", "Enhancing mass or fracture at the jugular foramen when the ninth and tenth nerves are also involved.", sequence="T1+Gd"), pathol("Nerve transection", "US", "Discontinuity or neuroma of the nerve in the posterior triangle after surgery.", sequence="n/a")],
 ["Lymph node biopsy or neck dissection", "Carotid endarterectomy, cervical surgery", "Blunt trauma or stretch", "Jugular foramen tumor", "Radiation"],
 [("Long thoracic nerve palsy", "Medial winging on pushing against a wall; shrug and abduction above the head preserved"), ("C5–C6 radiculopathy", "Deltoid and biceps weakness with sensory loss; trapezius spared"), ("Rotator cuff tear", "Painful weak abduction without winging or trapezius wasting"), ("Facioscapulohumeral dystrophy", "Bilateral, with facial weakness")],
 ["Early exploration and repair when the nerve is injured at surgery; EMG at 4–6 weeks if the deficit persists", "Physiotherapy to preserve shoulder range; sling for pain", "Eden–Lange tendon transfer for permanent palsy"],
 [B(14, 126)], marker=nerve("cn-11-accessory-l"), imagingHint=hint("axial", -30, -30, -40, "accessory nerve at the jugular foramen; the injury site is lower in the posterior triangle"), preset="lateral-l", **X))

E.append(syn("syn-physiologic-anisocoria", "Physiologic anisocoria and the approach to unequal pupils", "functional-pattern", ["cn-03-oculomotor", "ganglion-ciliary", "cervical-sympathetic-chain"], "n/a",
 "A patient, or a nurse, notices that one pupil is larger than the other. The size difference is under a millimeter, is the same in bright and dim light, both pupils react briskly, the lids are level and old photographs show the same asymmetry: this is physiologic anisocoria, present in a fifth of healthy people. If instead the difference is greater in the dark the small pupil is at fault (Horner), and if greater in the light the large pupil is at fault (third nerve, Adie, pharmacologic).",
 [D("pupil", "n/a", "both pupils", "Anisocoria under 1 mm, equal in light and dark, brisk reactions, normal lids and motility; benign", "pathway-pupillary-light-reflex"), D("pupil", "ipsilateral", "smaller pupil (pathologic)", "Anisocoria greater in the dark with dilation lag and mild ptosis: Horner syndrome", "pathway-oculosympathetic"), D("pupil", "ipsilateral", "larger pupil (pathologic)", "Anisocoria greater in the light with poor light reaction: third nerve palsy (with ptosis and ophthalmoplegia), Adie tonic pupil (slow near response) or pharmacologic mydriasis (no response to pilocarpine)", "cn-03-oculomotor")],
 "Pupil size is the balance between the sphincter, driven by the parasympathetic fibers from the Edinger–Westphal nucleus through the third nerve and ciliary ganglion, and the dilator, driven by the three-neuron sympathetic chain, and both systems serve each eye separately and without crossing, so an efferent lesion produces an asymmetry between the two pupils, whereas an afferent lesion never does, because each retina drives both Edinger–Westphal nuclei equally. Which pupil is abnormal is found by changing the light: in darkness the dilator is working, so a paralyzed dilator leaves its pupil behind and the anisocoria grows, revealing a Horner syndrome on the side of the smaller pupil; in bright light the sphincter is working, so a paralyzed sphincter leaves its pupil large and the anisocoria grows, revealing a parasympathetic lesion on the side of the larger pupil. Physiologic anisocoria arises from a slight asymmetry of central inhibition of the Edinger–Westphal nuclei and therefore stays constant across lighting conditions, with normal reactions and no ptosis. The pharmacologic tests follow the same logic: apraclonidine reverses Horner anisocoria by stimulating the supersensitive dilator, dilute pilocarpine constricts the supersensitive Adie sphincter, and full-strength pilocarpine fails to constrict a pharmacologically blocked pupil but constricts a third nerve palsy pupil. Old photographs are the cheapest test of all.",
 [pathol("Physiologic anisocoria", "MRI", "No imaging needed; if obtained for other reasons the study is normal.", sequence="n/a"), pathol("Pathologic anisocoria", "MRA", "Imaging follows the pattern: neck and skull base for Horner (carotid dissection), CTA for a pupil-involving third nerve palsy (posterior communicating aneurysm).", sequence="n/a")],
 ["Physiologic (20% of the population)", "Horner syndrome", "Third nerve palsy", "Adie tonic pupil", "Pharmacologic (scopolamine patch, nebulized ipratropium, plant alkaloids)", "Iris trauma or synechiae, acute angle closure"],
 [("Horner syndrome", "Anisocoria greater in the dark, ptosis, dilation lag"), ("Third nerve palsy", "Anisocoria greater in the light with ptosis and ophthalmoplegia"), ("Pharmacologic mydriasis", "Very large pupil unresponsive to 1% pilocarpine; history of exposure")],
 ["Measure the pupils in bright and dim light; examine the lids, eye movements and old photographs", "Anisocoria greater in the dark: apraclonidine test and Horner workup; greater in the light: check motility and pupil reactions, then pilocarpine tests", "Physiologic anisocoria with normal reactions and no other sign needs no investigation"],
 [B(10, 87, 90)], marker=structs("ciliary-ganglion-l", "ciliary-ganglion-r"), imagingHint=hint("axial", 0, 35, -12, "both eyes: the pupils are compared, not imaged"), preset="anterior", **X))

E.append(syn("syn-anosmia", "Anosmia and olfactory localization", "traumatic", ["cn-01-olfactory", "lobe-frontal", "gyrus-parahippocampal-uncus"], "bilateral",
 "A patient who fell and struck the back of the head can no longer smell coffee or gas and finds food tasteless. Another, with a slowly changing personality, has lost the sense of smell in one nostril without noticing, and has a swollen optic disc on the other side. Testing each nostril separately with familiar non-irritant odors reveals the loss; ammonia, which is felt through the trigeminal nerve, is still detected and unmasks a functional complaint.",
 [D("cranial-nerve", "bilateral", "both nostrils", "Anosmia or hyposmia to non-irritant odors with preserved perception of irritants (trigeminal)", "cn-01-olfactory"), D("cranial-nerve", "ipsilateral", "one nostril", "Unilateral anosmia from a bulb or tract lesion, usually unnoticed by the patient", "cn-01-olfactory"), D("other", "n/a", "taste (apparent)", "Complaint of loss of taste from loss of flavor; sweet, salt, sour and bitter preserved", "pathway-gustatory"), D("cognitive", "n/a", "frontal", "Personality change and apathy with a subfrontal tumor; Foster Kennedy syndrome with ipsilateral optic atrophy and contralateral papilledema", "lobe-frontal")],
 "Olfactory receptor neurons in the roof of the nasal cavity send unmyelinated axons in bundles through the cribriform plate to the olfactory bulb, which lies on the plate under the frontal lobe; the bulb's output runs back in the olfactory tract to the piriform cortex of the uncus and the amygdala, mostly on the same side, with a smaller crossed component through the anterior commissure. Because the pathway is largely uncrossed and each nostril is served by its own bulb, unilateral anosmia localizes to the nasal cavity, cribriform plate, bulb or tract of that side, and a unilateral loss is the earliest sign of an olfactory groove meningioma, which then compresses the optic nerve on the same side and raises intracranial pressure, producing the classic combination of ipsilateral optic atrophy and contralateral papilledema. Bilateral loss most often reflects disease of the nasal mucosa or a shearing injury of the olfactory filaments against the cribriform plate when the brain moves on impact, especially with occipital blows. Cortical lesions rarely abolish smell because the projection is bilateral at the level of the piriform cortex, but irritative lesions of the uncus produce olfactory hallucinations. Flavor depends on retronasal smell, so anosmic patients complain of tasteless food although the gustatory pathway is intact. Loss of smell is also an early sign of Parkinson and Alzheimer disease, in which the olfactory bulb is among the first structures affected.",
 [pathol("Post-traumatic anosmia", "MRI", "Contusion of the gyrus recti and orbital frontal cortex, hemosiderin on SWI, and atrophy of the olfactory bulbs on coronal thin-section T2.", sequence="SWI"), pathol("Olfactory groove meningioma", "MRI", "Enhancing subfrontal extra-axial mass on the cribriform plate displacing the frontal lobes and optic nerves, with hyperostosis on CT.", sequence="T1+Gd"), pathol("Sinonasal disease", "CT", "Mucosal thickening, polyps or obstruction of the olfactory cleft on sinus CT.", sequence="CT non-contrast"), pathol("Olfactory bulb volume loss", "MRI", "Small or absent bulbs in Kallmann syndrome (congenital) and reduced volume in post-viral and neurodegenerative anosmia.", sequence="T2")],
 ["Upper respiratory viral infection (including COVID-19)", "Chronic rhinosinusitis and polyps", "Head injury", "Olfactory groove or planum meningioma", "Parkinson and Alzheimer disease (early)", "Kallmann syndrome (with hypogonadism)", "Toxins, smoking, aging"],
 [("Ageusia", "True taste loss is rare; test the four tastes on the tongue"), ("Functional anosmia", "Claims not to detect ammonia, which is a trigeminal stimulus"), ("Nasal obstruction", "Conductive loss that fluctuates and responds to decongestants")],
 ["Test each nostril with non-irritant odors and with ammonia; formal olfactory testing kits for quantification", "MRI with coronal thin sections through the anterior cranial fossa for unilateral or unexplained anosmia; sinus CT for suspected mucosal disease", "Safety counseling: gas detectors, food dating; olfactory training after viral loss"],
 [S(11, 349), B(14, 125)], marker=sphere(0, 40, -20, 10), imagingHint=hint("coronal", 0, 40, -20, "olfactory bulbs on the cribriform plate beneath the frontal lobes"), preset="inferior", eponyms=["Foster Kennedy syndrome (with a subfrontal mass)"], **X))

E.append(syn("syn-transverse-myelitis", "Transverse myelitis", "demyelinating", ["spinal-cord", "spinal-white-columns", "spinal-grey-anterior-horn", "intermediolateral-column"], "bilateral",
 "Over hours to a few days a previously well adult develops back pain, numbness rising from the feet to a level on the trunk, weakness of both legs and difficulty passing urine. Examination shows a sensory level to pin-prick, bilateral leg weakness that is flaccid at first and later spastic, and urinary retention. MRI shows a swollen, T2-bright segment of the cord; the length of the lesion and the findings in the brain and optic nerves decide between multiple sclerosis, neuromyelitis optica and a post-infectious or systemic cause.",
 [D("motor", "bilateral", "below the lesion", "Paraparesis or quadriparesis, flaccid then spastic with extensor plantars", "pathway-lateral-corticospinal"), D("sensory-light-touch", "bilateral", "below a sensory level", "Loss of all modalities with a defined level, often with a band of pain or dysesthesia at the level", "pathway-dcml"), D("sphincter", "bilateral", "bladder and bowel", "Urinary retention then urgency; constipation", "intermediolateral-column"), D("pain", "bilateral", "back, radicular", "Back pain and Lhermitte sign", "spinal-white-columns"), D("autonomic", "bilateral", "below the lesion", "Autonomic dysreflexia and sweating changes with cervical or upper thoracic lesions", "sympathetic-trunk")],
 "Inflammation of one or a few segments of the cord, whether from a demyelinating attack, a post-infectious immune reaction or a systemic disease, damages the gray matter and all the white matter tracts crossing that level on both sides, so the picture is that of a partial or complete cord transection: the corticospinal tracts, which crossed in the medulla and serve the same-side limbs, are interrupted bilaterally, the posterior columns, uncrossed until the medulla, and the spinothalamic tracts, crossed within the cord, are all affected, giving bilateral loss of every modality below a level that corresponds to the inflamed segment, and the autonomic pathways to the bladder and bowel fail. The dorsal root entry zone at the lesion accounts for the band of pain, and involvement of the anterior horns at the level for any segmental flaccid weakness. Which disease is present is inferred from the shape of the lesion: multiple sclerosis produces short, eccentric, partial lesions of less than two segments, often dorsolateral and asymmetric, giving a partial myelitis; neuromyelitis optica produces longitudinally extensive, centrally located lesions spanning three or more segments with severe bilateral deficits; and acute disseminated encephalomyelitis, infections and connective tissue diseases produce variable patterns with brain or systemic clues. Spinal shock accounts for the initial flaccidity and areflexia. The main differential is a compressive or vascular lesion, which imaging separates within hours.",
 [pathol("Transverse myelitis", "MRI", "Intramedullary T2 hyperintensity with cord swelling and patchy enhancement over one to several segments; no extrinsic compression. Longitudinally extensive (three or more segments) lesions favor neuromyelitis optica or MOG antibody disease; short, eccentric lesions favor multiple sclerosis.", sequence="T2"), pathol("Brain and optic nerve lesions", "MRI", "Periventricular and juxtacortical lesions (MS), optic nerve enhancement or diencephalic and area postrema lesions (NMOSD).", sequence="FLAIR"), pathol("Inflammatory CSF", "LP/CSF", "Lymphocytic pleocytosis and raised protein; oligoclonal bands in MS, usually absent in NMOSD.", sequence="n/a")],
 ["Multiple sclerosis", "Neuromyelitis optica spectrum disorder (aquaporin-4)", "MOG antibody-associated disease", "Post-infectious and post-vaccination myelitis", "Systemic lupus, Sjögren syndrome, sarcoidosis, Behçet disease", "Viral myelitis (enterovirus, herpes viruses, HIV), Lyme, syphilis", "Idiopathic"],
 [("Compressive myelopathy (disc, tumor, abscess, hematoma)", "Extrinsic lesion on MRI; treatment is surgical"), ("Spinal cord infarct", "Onset within minutes, anterior cord pattern, restricted diffusion, aortic disease"), ("Guillain–Barré syndrome", "No sensory level, areflexia, cranial nerves, CSF protein high without cells"), ("Dural arteriovenous fistula", "Stepwise progressive myelopathy with flow voids on the cord surface")],
 ["Urgent MRI of the whole spine with contrast and of the brain; lumbar puncture, aquaporin-4 and MOG antibodies, infectious and systemic serology", "High-dose intravenous methylprednisolone; plasma exchange for poor responders; disease-modifying therapy according to the diagnosis", "Bladder management, thromboprophylaxis and rehabilitation"],
 [B(5, 45), B(21, 225, 227)], marker=sphere(0, -45, -100, 10), imagingHint=hint("sagittal", 0, -45, -100, "thoracic cord segment"), preset="posterior", **X))

E.append(syn("syn-poliomyelitis", "Poliomyelitis and anterior horn cell disease", "infectious", ["spinal-grey-anterior-horn", "motor-unit", "nucleus-ambiguus", "hypoglossal-nucleus"], "bilateral",
 "A child, unvaccinated or in an outbreak, has a febrile illness with headache and neck stiffness and then, over a day or two, develops weakness that is patchy and asymmetric, worse in the legs, with pain and fasciculation in the affected muscles. The weak limbs are flaccid and areflexic but sensation is normal and the bladder recovers quickly. Decades later some survivors develop new weakness and fatigue in the same muscles, the post-polio syndrome. Enterovirus and West Nile virus now produce the same picture.",
 [D("motor", "bilateral", "limbs, asymmetric and patchy, proximal and legs more than arms", "Acute flaccid paralysis with wasting and fasciculation; no sensory loss", "spinal-grey-anterior-horn"), D("reflex", "bilateral", "affected limbs", "Areflexia in the paralyzed muscles", "spinal-grey-anterior-horn"), D("bulbar", "bilateral", "palate, pharynx, larynx, face", "Bulbar palsy with dysphagia and respiratory failure in the bulbar form", "nucleus-ambiguus"), D("sensory-light-touch", "n/a", "spared", "Normal sensation, the key feature separating it from Guillain–Barré and myelitis", "pathway-dcml")],
 "Poliovirus, an enterovirus that enters through the gut, spreads to the central nervous system and infects the large motor neurons of the anterior horn and the motor nuclei of the brainstem selectively, destroying them and producing a purely lower motor neuron paralysis. The anterior horn cell is the final common pathway to muscle, so its death causes flaccid weakness with loss of the stretch reflex, whose efferent limb it forms, and denervation with wasting and fasciculation, while the sensory pathways, the dorsal horn and the long tracts are spared, so sensation is normal. Because the virus attacks scattered groups of motor neurons at different segments, the paralysis is asymmetric and patchy rather than following a level, unlike myelitis, and each side is affected independently, so there is no crossed or lateralized rule; the lumbar enlargement is affected most, and the bulbar nuclei in a minority, where involvement of the nucleus ambiguus and the respiratory centers is life-threatening. The preceding meningitic phase reflects the viral meningitis that accompanies the neuronal invasion. Surviving motor neurons sprout to re-innervate orphaned fibers, forming giant motor units; their later exhaustion after decades of overuse is the post-polio syndrome. Other enteroviruses (EV-D68, EV-A71), West Nile virus and spinal muscular atrophy produce the same anterior horn pattern by infection or degeneration.",
 [pathol("Acute anterior horn involvement", "MRI", "T2 hyperintensity of the anterior horns (gray matter) over several segments, often asymmetric, without white matter change; brainstem nuclei may enhance in the bulbar form.", sequence="T2"), pathol("Viral meningitis phase", "LP/CSF", "Lymphocytic pleocytosis with mildly raised protein; virus isolated from stool or throat, PCR of CSF for enteroviruses and West Nile virus.", sequence="n/a"), EMG("Acute denervation in a patchy multisegmental distribution with normal sensory conduction; later giant motor units from reinnervation.")],
 ["Poliovirus types 1–3 (wild or vaccine-derived)", "Non-polio enteroviruses (EV-D68, EV-A71) causing acute flaccid myelitis", "West Nile virus", "Spinal muscular atrophy (genetic, symmetric)"],
 [("Guillain–Barré syndrome", "Symmetric, ascending, with sensory symptoms and raised CSF protein without cells; no fever at onset"), ("Transverse myelitis", "Sensory level, sphincter involvement, upper motor neuron signs later"), ("Botulism", "Descending paralysis with ophthalmoplegia and dilated pupils"), ("Amyotrophic lateral sclerosis", "Chronic, with upper motor neuron signs")],
 ["Isolate the patient, notify public health, collect stool and CSF for virus identification; supportive care with respiratory monitoring", "Physiotherapy and orthoses; avoid overexertion of weak muscles", "Vaccination of contacts; recognize post-polio syndrome and manage fatigue and new weakness conservatively"],
 [S(4, 166), S(4, 169)], marker=sphere(0, -50, -150, 10), imagingHint=hint("axial", 0, -50, -150, "anterior horns of the lumbar enlargement"), preset="posterior", eponyms=["infantile paralysis", "acute flaccid myelitis"], **X))

E.append(syn("syn-lumbar-stenosis", "Lumbar spinal stenosis (neurogenic claudication)", "compressive", ["cauda-equina", "roots-l2-s1", "spinal-nerve-root-dermatome"], "bilateral",
 "An older patient reports that walking brings on aching, heaviness and tingling in the buttocks and legs that force them to stop after a few hundred meters, and that the symptoms fade over minutes when they sit or lean forward on a shopping trolley; walking uphill and cycling are easier than walking downhill. At rest the examination is nearly normal, with mild reflex loss at most, and the pedal pulses are present. The distance walked before symptoms shrinks over years.",
 [D("pain", "bilateral", "buttocks, thighs and calves, often asymmetric", "Neurogenic claudication: pain and paresthesias on standing and walking, relieved by sitting and lumbar flexion", "cauda-equina"), D("motor", "bilateral", "legs", "Weakness or heaviness after walking; mild fixed weakness (foot drop) in advanced cases", "roots-l2-s1"), D("reflex", "bilateral", "ankles and knees", "Reduced or absent ankle reflexes, sometimes after exercise only", "roots-l2-s1"), D("sphincter", "bilateral", "bladder (late)", "Urgency or retention with severe central stenosis", "cauda-equina")],
 "Degenerative narrowing of the lumbar canal by disc bulging, facet joint hypertrophy and a thickened ligamentum flavum, usually at L4–L5 and L3–L4, compresses the cauda equina and its blood supply. The canal is narrowest in extension, when the ligamentum flavum buckles inward and the disc bulges, and widest in flexion, so standing and walking, which extend the spine, provoke the symptoms and sitting, bending forward and cycling relieve them, the opposite of the vascular claudication that depends only on muscle work and is relieved by standing still. The roots of the cauda equina are peripheral nerve roots, so the deficit when it appears is lower motor neuron and radicular, with areflexia and dermatomal or multiradicular sensory symptoms, bilateral because the stenosis is central but often asymmetric, and there is no crossing to reason about because the lesion is below the cord. The intermittent nature of the symptoms is attributed to venous congestion and ischemia of the compressed roots during standing, which resolve on flexion, so the resting examination is often normal and a walk down the corridor before re-examination is the most useful bedside test. Lateral recess and foraminal stenosis produce a single-root picture instead, and severe central stenosis can progress to a cauda equina syndrome.",
 [pathol("Central lumbar stenosis", "MRI", "Trefoil canal with obliteration of the CSF around the cauda equina, ligamentum flavum hypertrophy and facet arthropathy at one or more levels on axial T2; redundant, tortuous roots above the stenosis.", sequence="T2"), pathol("Degenerative spondylolisthesis", "CT", "Forward slip of L4 on L5 with facet arthropathy narrowing the canal; upright or flexion-extension views show instability.", sequence="CT non-contrast"), EMG("Often normal at rest; multiradicular chronic denervation in advanced cases, useful to exclude polyneuropathy.")],
 ["Degenerative spondylosis with facet and ligamentum flavum hypertrophy", "Degenerative spondylolisthesis", "Congenitally narrow canal", "Epidural lipomatosis", "Ankylosing spondylitis, Paget disease"],
 [("Vascular claudication", "Calf pain with a fixed walking distance, relieved by standing still, absent pulses; ABI reduced"), ("Hip osteoarthritis", "Groin pain with hip rotation, limited range"), ("Peripheral neuropathy", "Constant distal sensory loss unrelated to posture"), ("Cervical or thoracic myelopathy", "Spastic gait with upper motor neuron signs")],
 ["MRI of the lumbar spine correlated with the symptoms; walking test before re-examination", "Physiotherapy in flexion, analgesia, epidural steroid injection for temporary relief", "Decompressive laminectomy, with fusion when there is spondylolisthesis, for disabling claudication"],
 [B(17, 159)], marker=sphere(0, -50, -180, 10), imagingHint=hint("sagittal", 0, -50, -180, "lumbar canal at L3–L5"), preset="posterior", eponyms=["neurogenic intermittent claudication"], **X))

E.append(syn("syn-parsonage-turner", "Neuralgic amyotrophy (Parsonage–Turner syndrome)", "plexopathy", ["plexus-brachial", "nerve-long-thoracic", "nerve-suprascapular", "nerve-axillary"], "ipsilateral",
 "A young adult wakes with excruciating pain in one shoulder that lasts for days to two weeks and is unrelieved by position or ordinary analgesics; as the pain subsides, weakness and rapid wasting appear in the shoulder girdle, most often the serratus anterior, supraspinatus, infraspinatus and deltoid, with winging of the scapula. Sensory loss is minor, often a patch over the deltoid. The pattern of weakness fits several nerves and roots at once. Recovery takes months to years.",
 [D("pain", "ipsilateral", "shoulder and upper arm", "Severe neuropathic pain for days to weeks preceding the weakness", "plexus-brachial"), D("motor", "ipsilateral", "shoulder girdle: serratus anterior, spinati, deltoid, biceps, in patchy combinations", "Weakness and rapid wasting appearing as the pain fades; scapular winging", "nerve-long-thoracic"), D("sensory-light-touch", "ipsilateral", "lateral shoulder (axillary) or minor patches", "Mild sensory loss out of proportion to the motor deficit", "nerve-axillary"), D("motor", "ipsilateral", "diaphragm, anterior interosseous (variants)", "Orthopnea from phrenic involvement; pinch weakness from anterior interosseous involvement", "nerve-phrenic")],
 "Neuralgic amyotrophy is an inflammatory, presumably immune-mediated attack on the brachial plexus and its branches, often following an infection, vaccination, surgery or childbirth, and in a hereditary form linked to SEPT9 mutations. The inflammation strikes individual nerves and fascicles rather than the plexus as a whole, which is why the deficits are patchy and fit several different nerves at once: the long thoracic nerve to the serratus anterior, the suprascapular nerve to the spinati, the axillary nerve to the deltoid, the anterior interosseous nerve to the long flexors of the thumb and index, and the phrenic nerve, in any combination, without matching any single root or trunk. The lesions are peripheral and uncrossed, so everything is ipsilateral, though a fifth of patients have bilateral, asymmetric involvement. Motor fascicles are affected far more than sensory ones, explaining the striking wasting with little sensory loss, and the pain reflects the acute inflammation of the nerve trunks. Nerve imaging shows focal constrictions and swelling of the affected nerves, sometimes with an hourglass appearance, which supports the diagnosis and separates it from a cervical radiculopathy, in which the pain and weakness follow a single root and paraspinal muscles are denervated, and from a rotator cuff injury, which has no neurogenic wasting.",
 [EMG("Denervation in muscles of several different nerves and roots of one limb without paraspinal involvement; reduced sensory responses in the affected nerves (postganglionic)."), pathol("Nerve inflammation", "MRI", "T2 hyperintensity and enlargement of the affected plexus elements or individual nerves on MR neurography, with denervation edema of the shoulder girdle muscles on STIR; hourglass constrictions on high-resolution ultrasound.", sequence="STIR"), pathol("Cervical spine (exclusion)", "MRI", "No compressive root lesion matching the deficit.", sequence="T2")],
 ["Idiopathic (post-infectious, post-surgical, postpartum)", "Hereditary neuralgic amyotrophy (SEPT9)", "Immunization", "Strenuous exercise"],
 [("Cervical radiculopathy", "Pain and weakness confined to one root, paraspinal denervation, compression on MRI"), ("Rotator cuff tear", "Weakness limited by pain without wasting or denervation"), ("Traumatic plexopathy", "History of stretch injury; deficits follow trunks or cords"), ("Multifocal motor neuropathy", "Painless, slowly progressive, conduction block")],
 ["Strong analgesia in the painful phase; corticosteroids in the first two weeks may shorten it", "Physiotherapy to maintain range and prevent frozen shoulder; EMG at 3–4 weeks to define the extent", "Reassurance about slow recovery over 1–3 years; nerve exploration only for persistent hourglass constrictions"],
 [B(15, 131), B(16, 147)], marker=nerve("brachial-plexus-l"), imagingHint=hint("coronal", -60, -20, -40, "brachial plexus and its shoulder girdle branches"), preset="anterior", eponyms=["brachial neuritis", "idiopathic brachial plexopathy"], **X))

E.append(syn("syn-axillary-neuropathy", "Axillary nerve palsy", "traumatic", ["nerve-axillary", "plexus-brachial"], "ipsilateral",
 "After an anterior shoulder dislocation or a fracture of the surgical neck of the humerus, a patient cannot lift the arm sideways once the first few degrees are achieved by the supraspinatus, the rounded contour of the shoulder flattens as the deltoid wastes, and there is a patch of numbness over the outer upper arm. External rotation may be mildly weak from teres minor involvement. Sleeping with the arm over a chair back or crutch pressure can produce the same picture.",
 [D("motor", "ipsilateral", "deltoid and teres minor", "Weak abduction beyond 15–30° and forward flexion; flattened shoulder contour with wasting", "nerve-axillary"), D("sensory-light-touch", "ipsilateral", "'regimental badge' area over the lateral deltoid", "Sensory loss over the upper lateral arm (upper lateral cutaneous nerve of the arm)", "nerve-axillary"), D("motor", "n/a", "supraspinatus and other C5 muscles", "Initial abduction and elbow flexion preserved, separating it from C5 root and upper trunk lesions", "nerve-suprascapular")],
 "The axillary nerve is a terminal branch of the posterior cord carrying C5 and C6 fibers; it leaves the axilla backward through the quadrangular space beneath the shoulder joint capsule, curls around the surgical neck of the humerus with the posterior circumflex humeral vessels and supplies the deltoid and teres minor and a patch of skin over the deltoid. Its intimate relation to the inferior joint capsule and the surgical neck is why an anterior dislocation of the humeral head or a fracture at the surgical neck stretches or tears it, and why it is at risk during shoulder surgery and from crutches pressing into the axilla. It is an uncrossed peripheral nerve, so the deficit is on the side of the injury: the deltoid, the main abductor and flexor of the shoulder, is paralyzed, but the supraspinatus, supplied by the suprascapular nerve, still initiates abduction, so the first few degrees are possible and the patient compensates by hitching the shoulder. The sensory territory is small and constant, over the deltoid, and its loss confirms the nerve rather than a root: a C5 radiculopathy would weaken the supraspinatus, the biceps and the rhomboids as well and produce a broader sensory loss with neck pain. Most closed injuries are neurapraxic and recover within months, and the deltoid is examined after every shoulder dislocation and before its reduction.",
 [EMG("Denervation confined to the deltoid and teres minor with reduced axillary motor amplitude; normal supraspinatus, biceps and paraspinals."), pathol("Shoulder dislocation or humeral fracture", "CT", "Anterior glenohumeral dislocation, Hill–Sachs lesion or surgical neck fracture; the nerve is inferred rather than seen.", sequence="CT non-contrast"), pathol("Quadrilateral space syndrome", "MRI", "Fatty atrophy of the teres minor and deltoid with a mass or fibrous band in the quadrangular space on MR.", sequence="T1")],
 ["Anterior shoulder dislocation", "Fracture of the surgical neck of the humerus", "Shoulder surgery and intramuscular injection", "Crutch or sleep compression", "Quadrilateral space syndrome (athletes)", "Neuralgic amyotrophy"],
 [("C5 radiculopathy", "Supraspinatus, biceps and rhomboids also weak; neck pain; sensory loss broader"), ("Rotator cuff tear", "Painful weak abduction with normal sensation and no deltoid wasting"), ("Upper trunk plexopathy", "Elbow flexion and external rotation weak; biceps reflex lost")],
 ["Document deltoid function and lateral arm sensation before and after reducing a shoulder dislocation", "Physiotherapy to maintain range; EMG at 3–4 weeks if no recovery", "Nerve exploration or grafting if there is no reinnervation by 3–6 months"],
 [B(16, 150)], marker=nerve("axillary-nerve-l"), imagingHint=hint("coronal", -80, -30, -60, "axillary nerve around the surgical neck of the humerus (virtual)"), preset="anterior", **X))

E.append(syn("syn-lumbosacral-plexopathy", "Lumbosacral plexopathy", "plexopathy", ["plexus-lumbosacral", "roots-l2-s1", "nerve-femoral", "nerve-sciatic", "nerve-obturator"], "ipsilateral",
 "A diabetic patient in their sixties develops severe pain in one thigh followed over weeks by weakness and wasting of the quadriceps and hip muscles, with loss of the knee jerk and marked weight loss; the other leg may follow. In a patient with pelvic cancer or after pelvic radiotherapy, a similar painful or painless leg weakness involves both femoral and sciatic territories, a distribution too wide for one nerve and too patchy for the cord.",
 [D("motor", "ipsilateral", "hip flexors, quadriceps, adductors (lumbar plexus) and/or gluteal, hamstring and leg muscles (sacral plexus)", "Weakness and wasting spanning several nerve and root territories", "plexus-lumbosacral"), D("pain", "ipsilateral", "thigh, buttock or leg", "Severe pain at onset (diabetic, neoplastic); painless in radiation plexopathy", "plexus-lumbosacral"), D("reflex", "ipsilateral", "knee and/or ankle", "Reduced knee reflex (lumbar) or ankle reflex (sacral)", "roots-l2-s1"), D("sensory-light-touch", "ipsilateral", "anterior thigh and medial leg, or posterior thigh, lateral leg and foot", "Multiradicular sensory loss without a level; perineum spared", "plexus-lumbosacral"), D("autonomic", "ipsilateral", "leg", "Leg edema and sympathetic changes with pelvic tumor; sphincters spared", "sympathetic-trunk")],
 "The lumbar plexus forms within the psoas from the L1–L4 roots and gives the femoral, obturator and lateral femoral cutaneous nerves; the sacral plexus forms on the piriformis from L4–S3 and gives the sciatic, gluteal and pudendal nerves. A lesion of the plexus, lying between the roots and the individual nerves, produces a deficit that is broader than any one nerve and does not follow one root: a lumbar plexopathy weakens hip flexion, knee extension and adduction together (femoral plus obturator territory), which a femoral neuropathy cannot do, and a sacral plexopathy weakens the glutei and the sciatic muscles together, which a sciatic lesion cannot do. The lesion is peripheral and ipsilateral, though the diabetic form often spreads to the other side after a delay. The perineum and sphincters are spared because the sacral roots to the pudendal nerve leave the plexus separately and the conus is intact, and there is no sensory level, which separates plexopathy from a conus or cauda equina lesion; sensory nerve action potentials are reduced because the lesion is distal to the dorsal root ganglia, which separates it from a radiculopathy, in which they are preserved, and paraspinal muscles are spared. Diabetic radiculoplexus neuropathy is an inflammatory microvasculitis of the roots and plexus; malignant plexopathy is infiltration from cervical, prostatic, colorectal or lymphomatous tumor, painful and progressive; radiation plexopathy appears years after treatment, is painless and shows myokymia on EMG; and a psoas hematoma or abscess compresses the lumbar plexus acutely.",
 [pathol("Plexus infiltration or compression", "MRI", "Enhancing tumor along the pelvic sidewall or in the psoas encasing the plexus; psoas hematoma or abscess displacing it; thickened enhancing plexus in diabetic and inflammatory forms on MR neurography.", sequence="T1+Gd"), pathol("Radiation plexopathy", "MRI", "Diffuse thickening and T2 change of the plexus within the radiation field without a discrete mass; myokymia on EMG.", sequence="STIR"), EMG("Denervation across several nerve territories of one limb sparing the paraspinal muscles, with reduced sensory responses (postganglionic); myokymic discharges in radiation plexopathy."), pathol("Lumbar spine (exclusion)", "MRI", "No root compression matching the deficit; excludes cauda equina lesion.", sequence="T2")],
 ["Diabetic lumbosacral radiculoplexus neuropathy (diabetic amyotrophy)", "Pelvic malignancy (cervix, prostate, colorectal, lymphoma, sarcoma)", "Radiation plexopathy", "Retroperitoneal or psoas hematoma (anticoagulation) or abscess", "Pelvic fracture or surgery, obstetric compression", "Idiopathic (non-diabetic) inflammatory plexopathy"],
 [("Lumbosacral polyradiculopathy", "Paraspinal denervation, preserved sensory responses, root compression or leptomeningeal enhancement on MRI"), ("Femoral or sciatic mononeuropathy", "Deficit confined to one nerve"), ("Cauda equina or conus lesion", "Bilateral, saddle anesthesia, sphincter loss"), ("Hip disease", "Pain on joint movement without neurological deficit")],
 ["MRI of the pelvis and lumbar spine with contrast; EMG to define the distribution and exclude radiculopathy; screen for diabetes and malignancy", "Diabetic amyotrophy: glycemic control, pain management, physiotherapy; immunotherapy is debated; recovery over 1–2 years", "Treat tumor or hematoma; radiation plexopathy is managed supportively"],
 [B(17, 163)], marker=nerve("lumbosacral-plexus-l"), imagingHint=hint("coronal", -40, -40, -180, "lumbosacral plexus in the psoas and on the pelvic sidewall (virtual)"), preset="anterior", eponyms=["diabetic amyotrophy (Bruns–Garland syndrome)"], **X))

E.append(syn("syn-mononeuritis-multiplex", "Mononeuritis multiplex", "metabolic-toxic", ["nerve-common-peroneal", "nerve-ulnar", "nerve-radial", "nerve-median", "nerve-tibial"], "bilateral",
 "A patient with a systemic illness, weight loss, fever, rash or a known connective tissue disease develops a painful foot drop, then weeks later numbness and weakness in the ulnar territory of the opposite hand, then a wrist drop. Each episode is a sudden, painful lesion of one named nerve, and the accumulation of several such lesions in a random, asymmetric pattern is the signature of nerve infarction from vasculitis, which needs urgent immunosuppression.",
 [D("motor", "bilateral", "individual named nerves, asymmetric and stepwise (peroneal, ulnar, radial, median, tibial)", "Acute painful weakness in one nerve's distribution, accumulating over weeks to months", "nerve-common-peroneal"), D("sensory-light-touch", "bilateral", "same nerve territories", "Sensory loss following named nerves rather than a stocking pattern", "nerve-ulnar"), D("pain", "bilateral", "affected nerves", "Deep aching and burning pain at the onset of each lesion", "nerve-radial"), D("other", "n/a", "systemic", "Fever, weight loss, purpura, arthralgia, renal or pulmonary involvement", "sympathetic-trunk")],
 "Each peripheral nerve is supplied by small vasa nervorum, and when these vessels are inflamed and occluded by vasculitis, whether polyarteritis nodosa, ANCA-associated vasculitis, rheumatoid or cryoglobulinemic vasculitis or a non-systemic vasculitic neuropathy, the nerve infarcts at the watershed between its nutrient arteries, in the mid-thigh for the sciatic and peroneal fibers and the mid-arm for the ulnar and radial nerves. Because infarcts occur one nerve at a time and at random, the deficits are asymmetric, follow the anatomy of named nerves rather than roots or a stocking-glove length-dependent pattern, and accumulate stepwise; the lesions are peripheral and each is ipsilateral to its own nerve, with no crossing to reason about, and the process is 'multiplex' because both sides are eventually involved. Pain is prominent because ischemia inflames the nerve and its sheath. With time the many overlapping nerve infarcts merge into a confluent asymmetric polyneuropathy that can be mistaken for a length-dependent one, so the history of stepwise nerve-by-nerve onset is decisive. Nerve conduction shows axonal loss in the affected nerves with preserved conduction in their neighbors, and biopsy of an affected nerve with its accompanying muscle shows the vasculitis. Diabetes, leprosy, sarcoidosis, HIV, hepatitis B and C, lymphoma and hereditary neuropathy with liability to pressure palsies produce multiple mononeuropathies by other mechanisms.",
 [EMG("Asymmetric axonal loss confined to individual nerves (reduced sensory and motor amplitudes) with normal neighboring nerves; later confluent asymmetric axonal polyneuropathy. Pseudo-conduction block early after an infarct."), pathol("Nerve and muscle biopsy", "MRI", "Imaging is normal; biopsy of the sural or superficial peroneal nerve with peroneus brevis shows transmural inflammation and fibrinoid necrosis of epineurial vessels with axonal loss. MR neurography may show focal nerve enlargement and enhancement.", sequence="T1+Gd"), pathol("Systemic vasculitis", "CTA", "Microaneurysms of the renal and mesenteric arteries in polyarteritis nodosa; pulmonary nodules or sinus disease in ANCA vasculitis.", sequence="CT contrast")],
 ["Polyarteritis nodosa", "ANCA-associated vasculitis (granulomatosis with polyangiitis, eosinophilic granulomatosis, microscopic polyangiitis)", "Rheumatoid, lupus and Sjögren vasculitis; cryoglobulinemia (hepatitis C)", "Non-systemic vasculitic neuropathy", "Diabetes, leprosy, sarcoidosis, HIV, lymphoma", "Hereditary neuropathy with liability to pressure palsies (painless)"],
 [("Length-dependent polyneuropathy", "Symmetric, distal, gradual, painless onset"), ("Multiple entrapment neuropathies", "Common sites (carpal tunnel, elbow, fibular head), painless, conduction slowing at the site"), ("Multifocal motor neuropathy", "Pure motor, conduction block, no pain"), ("Leprosy", "Thickened nerves, skin lesions, endemic exposure")],
 ["Urgent workup: ESR, CRP, ANCA, cryoglobulins, hepatitis serology, complement, urinalysis; EMG; nerve and muscle biopsy", "Immunosuppression with corticosteroids and cyclophosphamide or rituximab for systemic vasculitis; do not wait for biopsy if the picture is clear", "Neuropathic pain treatment and orthoses; monitor for renal and pulmonary involvement"],
 [B(27, 283, 287)], marker=nerve("common-peroneal-nerve-l", "ulnar-nerve-r"), imagingHint=hint("axial", 0, -45, -160, "lumbosacral roots: the lesions themselves are in named peripheral nerves"), preset="anterior", eponyms=["multiple mononeuropathy", "vasculitic neuropathy"], **X))

E.append(syn("syn-lambert-eaton", "Lambert–Eaton myasthenic syndrome", "neuromuscular", ["neuromuscular-junction", "motor-unit", "sympathetic-trunk"], "bilateral",
 "A long-term smoker develops weakness of the thighs and hips that makes rising from a chair and climbing stairs difficult, with aching muscles, a dry mouth and impotence. The weakness is worst after rest and improves briefly after a few seconds of effort; the reflexes are absent at first but appear after the patient contracts the muscle for ten seconds. Ptosis and diplopia are mild or absent, and swallowing is usually preserved. A small cell lung cancer is found in half the patients, sometimes years later.",
 [D("motor", "bilateral", "proximal legs then arms", "Proximal weakness that facilitates briefly with exercise", "neuromuscular-junction"), D("reflex", "bilateral", "generalized", "Absent or reduced reflexes that return after brief maximal contraction (post-exercise facilitation)", "motor-unit"), D("autonomic", "bilateral", "cholinergic", "Dry mouth, constipation, erectile dysfunction, orthostatic hypotension, reduced sweating", "sympathetic-trunk"), D("oculomotor", "bilateral", "mild", "Mild ptosis or diplopia; bulbar and respiratory involvement uncommon", "cn-03-oculomotor")],
 "Antibodies against the P/Q-type voltage-gated calcium channels of the presynaptic motor nerve terminal reduce the calcium entry that triggers acetylcholine release, so each nerve impulse releases too few quanta and the endplate potential often fails to reach threshold. The muscle fibers and their receptors are normal, so the defect is presynaptic, the reverse of myasthenia gravis: because repetitive stimulation at high frequency or a brief voluntary contraction lets calcium accumulate in the terminal, transmission improves for a few seconds, which is why strength and reflexes facilitate with exercise and why the compound muscle action potential increments by more than 100% on rapid repetitive stimulation, whereas in myasthenia it decrements. The same calcium channels operate at the terminals of autonomic cholinergic neurons, so the parasympathetic and sudomotor failure that gives the dry mouth, constipation and erectile dysfunction is part of the disease and helps separate it from myasthenia. The antibodies arise in about half of patients as an immune response to a small cell lung carcinoma, which expresses the same channels, and the neurological syndrome typically precedes the tumor's detection; the remainder are autoimmune without cancer, often with other autoimmune disease. Everything is bilateral and symmetric, a disorder of transmission rather than of any anatomical pathway, so there is no crossing or lateralization to consider.",
 [pathol("Presynaptic transmission defect", "EMG/NCS", "Small resting compound muscle action potentials, decrement at low-frequency stimulation, and an increment of over 100% after 10 seconds of maximal exercise or 50 Hz stimulation; increased jitter on single-fiber EMG.", sequence="n/a"), pathol("Small cell lung cancer", "CT", "Hilar or mediastinal mass on chest CT; FDG-PET if CT is negative, repeated over two years, since the tumor may lag the syndrome.", sequence="CT contrast"), pathol("Antibodies", "EMG/NCS", "Serology alongside electrodiagnosis: P/Q-type voltage-gated calcium channel antibodies in 85–90%; SOX1 antibodies favor a paraneoplastic cause.", sequence="n/a")],
 ["Paraneoplastic (small cell lung cancer)", "Autoimmune non-paraneoplastic (often with thyroid disease or type 1 diabetes)"],
 [("Myasthenia gravis", "Ocular and bulbar predominance, fatigability without facilitation, normal reflexes and autonomic function, decrement without increment"), ("Inflammatory myopathy", "Proximal weakness with raised CK and myopathic EMG; reflexes preserved"), ("Guillain–Barré or CIDP", "Sensory symptoms, demyelinating conduction changes"), ("Botulism", "Acute, descending, with ophthalmoplegia and dilated pupils; also presynaptic")],
 ["Confirm with repetitive stimulation and calcium channel antibodies; search for small cell lung cancer with CT and PET, repeated for two years", "Amifampridine (3,4-diaminopyridine) improves strength; pyridostigmine adds little; immunosuppression or IVIG for severe cases", "Treat the tumor: this often improves the neurological syndrome"],
 [B(30, 295, 297)], marker=structs("brainstem"), imagingHint=hint("axial", 0, -45, -160, "the defect is at neuromuscular junctions throughout the body; the lumbosacral roots stand in for the proximal legs"), preset="anterior", **X))

E.append(syn("syn-myopathy-pattern", "Myopathy: the muscle disease pattern", "neuromuscular", ["motor-unit", "neuromuscular-junction"], "bilateral",
 "A patient cannot rise from a low chair without using the arms, climbs stairs one at a time and cannot lift the arms to wash their hair, yet buttons, writing and walking on the flat are normal. The weakness is symmetric and proximal, the muscles are not wasted early and may be tender, the reflexes are preserved until the muscles are very weak, sensation is normal and there are no fasciculations. Dark urine, a rash over the knuckles and eyelids, or a family history each point to a cause.",
 [D("motor", "bilateral", "proximal limb girdles, neck flexors, symmetric", "Symmetric proximal weakness: Gowers sign, difficulty rising and lifting the arms; distal strength preserved", "motor-unit"), D("reflex", "bilateral", "generalized", "Reflexes preserved in proportion to strength; lost only late", "motor-unit"), D("sensory-light-touch", "n/a", "spared", "Normal sensation; no fasciculations", "dorsal-root-ganglion"), D("other", "bilateral", "muscle", "Myalgia, tenderness, cramps or contractures; myoglobinuria in necrotizing forms", "motor-unit"), D("bulbar", "bilateral", "pharynx, face, respiratory muscles (some myopathies)", "Dysphagia, facial weakness, ptosis or respiratory failure in specific diseases", "neuromuscular-junction")],
 "In a myopathy the disease is in the muscle fiber itself, whether inflammatory, dystrophic, metabolic, toxic or endocrine, and the nerve supply is intact. Because the largest, most metabolically active muscles of the limb girdles and trunk are affected first and most, the weakness is proximal and symmetric, in contrast to the distal, length-dependent weakness of neuropathy and the asymmetric, regional weakness of anterior horn cell disease; sensation is normal because the sensory nerves and roots are untouched, and fasciculations are absent because the motor neuron is healthy. The reflex arc is intact, so reflexes persist until the muscle is too weak to generate a visible contraction, unlike the early areflexia of neuropathy. Nothing crosses and nothing lateralizes; the pattern is bilateral and symmetric, and any marked asymmetry (facioscapulohumeral dystrophy, inclusion body myositis with its finger flexor and quadriceps predilection) is itself a clue to the specific disease. Damaged fibers leak creatine kinase, which is raised in inflammatory, dystrophic and necrotizing myopathies but normal in steroid and many endocrine myopathies, and EMG shows small, short, polyphasic motor units that recruit early, the electrical signature of fibers dropping out of intact motor units, the opposite of the large units of reinnervation. The specific diagnosis rests on the tempo, the distribution, the skin and systemic features, the enzyme level, imaging of muscle edema or fatty replacement, and biopsy or genetic testing.",
 [pathol("Myopathic pattern", "EMG/NCS", "Small, short-duration, polyphasic motor unit potentials with early recruitment; fibrillations in inflammatory and necrotizing myopathies; normal nerve conduction.", sequence="n/a"), pathol("Muscle edema and fatty replacement", "MRI", "STIR hyperintensity of inflamed muscles guiding biopsy in myositis; selective fatty infiltration patterns on T1 in dystrophies and inclusion body myositis.", sequence="STIR"), pathol("Serum creatine kinase", "EMG/NCS", "Serum CK measured alongside electrodiagnosis: markedly raised in polymyositis, necrotizing myopathy and dystrophinopathies; normal in steroid myopathy and mild in inclusion body myositis.", sequence="n/a")],
 ["Inflammatory: dermatomyositis, polymyositis, immune-mediated necrotizing myopathy, inclusion body myositis", "Endocrine and toxic: hypothyroidism, Cushing syndrome or steroids, statins, alcohol, colchicine", "Muscular dystrophies (Duchenne, Becker, limb-girdle, facioscapulohumeral, myotonic)", "Metabolic: glycogen and lipid storage, mitochondrial disease, periodic paralysis", "Critical illness myopathy"],
 [("Myasthenia gravis", "Fatigable ocular and bulbar weakness, normal CK, antibodies"), ("Motor neuron disease", "Fasciculations, wasting, upper motor neuron signs, asymmetric"), ("Proximal neuropathy (CIDP, diabetic amyotrophy)", "Areflexia, sensory loss, demyelinating conduction"), ("Polymyalgia rheumatica", "Pain and stiffness with normal strength and CK, raised ESR")],
 ["CK, thyroid function, EMG and muscle MRI; myositis antibody panel; biopsy or genetic testing as directed by the pattern", "Immunosuppression for inflammatory myopathies; stop offending drugs; treat endocrine causes", "Screen for malignancy in adult dermatomyositis; monitor respiratory and cardiac function in dystrophies"],
 [B(31, 301, 305)], marker=structs("brainstem"), imagingHint=hint("axial", 0, -45, -160, "the disease is in the muscles; the lumbosacral segments stand in for the limb girdles"), preset="anterior", **X))

E.append(syn("syn-cavernous-sinus-thrombosis", "Septic cavernous sinus thrombosis", "infectious", ["sinus-cavernous", "cn-06-abducens", "cn-03-oculomotor", "cn-05-trigeminal", "artery-internal-carotid"], "ipsilateral",
 "A patient with a boil on the upper lip or a sinus infection develops high fever, severe headache and a red, swollen, protruding eye with drooping lid; within a day the eye cannot move, the forehead is numb, the retinal veins are engorged and the other eye starts to swell as the infection crosses the midline. Untreated, meningitis, carotid narrowing with stroke and death follow within days; treated early with antibiotics and anticoagulation most survive.",
 [D("other", "ipsilateral", "orbit, then bilateral", "Painful proptosis, chemosis, lid edema and retinal venous engorgement from ophthalmic vein obstruction; spreads to the other eye within days", "sinus-cavernous"), D("oculomotor", "ipsilateral", "VI first, then III and IV", "Ophthalmoplegia beginning with abduction failure", "cn-06-abducens"), D("sensory-light-touch", "ipsilateral", "V1 and V2", "Forehead and cheek numbness, reduced corneal reflex", "cn-05-trigeminal"), D("consciousness", "bilateral", "diffuse", "Fever, rigors, drowsiness from sepsis and meningitis", "reticular-formation"), D("motor", "contralateral", "hemibody (complication)", "Hemiparesis from carotid arteritis and narrowing within the sinus", "artery-internal-carotid")],
 "The facial veins have no valves and drain into the cavernous sinus through the ophthalmic veins and the pterygoid plexus, so an infection of the central face, the orbit, the sphenoid or ethmoid sinuses, the teeth or the ear can propagate thrombophlebitis backward into the sinus. Within the sinus the thrombus obstructs the ophthalmic veins, congesting the orbit and retina on that side, and the inflammation involves the nerves in its walls, uncrossed nerves serving the ipsilateral eye and face: the abducens nerve, floating free beside the carotid, fails first, then the oculomotor and trochlear nerves in the lateral wall, and the ophthalmic and maxillary divisions of the trigeminal nerve, while the sympathetic plexus on the carotid may add a Horner. The two cavernous sinuses communicate through the intercavernous sinuses around the pituitary, so the thrombosis spreads across within days and the picture becomes bilateral, which is the clue that separates it from an orbital cellulitis or a tumor. The carotid artery runs through the sinus and can be narrowed by the surrounding inflammation, producing cerebral infarction, and the infection reaches the meninges and the pituitary. Staphylococcus aureus is the usual organism, and the diagnosis is confirmed by venography showing the filling defect and the dilated superior ophthalmic vein, though it should be treated on clinical suspicion.",
 [pathol("Cavernous sinus thrombophlebitis", "MRV", "Filling defect with expansion and convex bulging of the lateral walls of the cavernous sinus, dilated thrombosed superior ophthalmic vein, proptosis and orbital fat stranding; enhancement of the sinus walls and dura.", sequence="T1+Gd"), pathol("Source of infection", "CT", "Sphenoid or ethmoid sinusitis, facial cellulitis, dental or orbital abscess on contrast CT of the sinuses and orbits.", sequence="CT contrast"), pathol("Carotid narrowing and infarction", "MRA", "Narrowing of the cavernous carotid with cerebral infarcts on DWI; mycotic aneurysm later.", sequence="n/a")],
 ["Facial furuncle or cellulitis in the 'danger triangle'", "Sphenoid and ethmoid sinusitis", "Dental infection", "Orbital cellulitis", "Otitis and mastoiditis (via the petrosal sinuses)", "Invasive fungal sinusitis in diabetics and the immunosuppressed"],
 [("Orbital cellulitis", "Unilateral, cranial nerves spared initially, no contralateral spread"), ("Cavernous sinus tumor or Tolosa–Hunt", "No fever or sepsis, slower course, no venous engorgement"), ("Carotid-cavernous fistula", "Pulsating exophthalmos with a bruit, no fever"), ("Aseptic cavernous sinus thrombosis", "Prothrombotic state without infection")],
 ["Blood cultures then immediate high-dose intravenous antibiotics covering Staphylococcus aureus and anaerobes; drain the source", "Anticoagulation with heparin is generally recommended despite the risk of hemorrhage", "Steroids for pituitary insufficiency; antifungals and debridement if mucormycosis is suspected"],
 [S(15, 432, 433)], marker=sphere(-15, 5, -20, 10), imagingHint=hint("coronal", -15, 5, -20, "cavernous sinus beside the sella"), preset="anterior", **X))

E.append(syn("syn-huntington-chorea", "Huntington disease and chorea", "degenerative", ["caudate-nucleus", "putamen", "globus-pallidus", "cortex-prefrontal"], "bilateral",
 "A person in their forties whose parent died in a psychiatric hospital becomes irritable and depressed, then clumsy and fidgety; over a few years the fidgeting becomes continuous flowing, dance-like movements of the limbs, trunk and face, with an unsteady lurching gait, darting eyes that cannot hold fixation, and a slow decline in judgment and memory. The tongue cannot be kept protruded and the grip milks the examiner's fingers. In late disease the chorea gives way to rigidity and dystonia.",
 [D("other", "bilateral", "face, limbs, trunk", "Chorea: irregular, flowing, unpredictable involuntary movements incorporated into voluntary acts; motor impersistence", "pathway-basal-ganglia-loops"), D("cognitive", "bilateral", "frontostriatal", "Executive dysfunction, slowed thinking, later dementia", "caudate-nucleus"), D("cognitive", "bilateral", "limbic loop", "Depression, irritability, apathy, obsessional traits, psychosis; high suicide risk", "cortex-prefrontal"), D("oculomotor", "bilateral", "saccades", "Slow, delayed saccade initiation with head thrusts; impersistence of gaze", "frontal-eye-field"), D("gait", "bilateral", "gait and posture", "Lurching, wide-based gait with falls; late rigidity and dystonia (Westphal variant in juvenile onset)", "pathway-basal-ganglia-loops")],
 "An expanded CAG repeat in the huntingtin gene produces a protein that kills the medium spiny neurons of the striatum, beginning with those of the indirect pathway, which express D2 receptors and enkephalin and project to the external pallidum. Losing them removes the striatal inhibition of the external pallidum, which then over-inhibits the subthalamic nucleus, so the subthalamic excitation of the internal pallidum falls, the internal pallidum's inhibition of the thalamus weakens, and the motor thalamus and cortex are released: fragments of movement escape as chorea, the mirror image of the excessive inhibition of parkinsonism and the functional equivalent of a subthalamic lesion, but bilateral and gradual. Each striatum serves the contralateral body through the crossed corticospinal projection, and the degeneration is bilateral and symmetric, so the chorea is generalized. As the disease advances the direct pathway neurons die too and the output nuclei regain inhibitory dominance, so rigidity and bradykinesia replace the chorea, which also explains why juvenile-onset disease, in which both pathways degenerate early, presents with rigidity. The caudate, which connects the prefrontal cortex to the pallidum in the associative and limbic loops, atrophies visibly, and its loss underlies the executive, behavioral and psychiatric changes that often precede the movement disorder. Chorea from other causes, Sydenham chorea after streptococcal infection, lupus, drugs, thyrotoxicosis, pregnancy and stroke, involves the same striatal circuit by other mechanisms.",
 [pathol("Caudate atrophy", "MRI", "Loss of the convex bulge of the caudate heads into the frontal horns ('boxcar' ventricles) with putaminal atrophy and later diffuse cortical atrophy; reduced caudate uptake on FDG-PET precedes atrophy.", sequence="T1"), pathol("Genetic diagnosis", "MRI", "Imaging supports but does not make the diagnosis: CAG repeat expansion of 36 or more in the HTT gene; predictive testing requires genetic counseling.", sequence="n/a"), pathol("Secondary chorea (mimic)", "MRI", "Striatal T1 hyperintensity in hyperglycemia, infarct or vasculitis of the striatum, or normal imaging in Sydenham and drug-induced chorea.", sequence="FLAIR")],
 ["Huntington disease (autosomal dominant CAG repeat expansion)", "Huntington-like syndromes (C9orf72, HDL2), neuroacanthocytosis, spinocerebellar ataxias", "Sydenham chorea, lupus and antiphospholipid syndrome", "Drugs (levodopa, dopamine blockers causing tardive dyskinesia, anticonvulsants, oral contraceptives)", "Thyrotoxicosis, polycythemia, hyperglycemia, chorea gravidarum", "Striatal or subthalamic stroke (hemichorea)"],
 [("Tardive dyskinesia", "Orofacial stereotypies with a history of dopamine blockers; no cognitive decline"), ("Sydenham chorea", "Child or young adult after streptococcal infection, self-limiting"), ("Wilson disease", "Young, with dystonia, tremor, Kayser–Fleischer rings and liver disease"), ("Essential tremor or tics", "Rhythmic tremor or suppressible stereotyped tics")],
 ["Genetic testing with counseling; exclude treatable causes of chorea in atypical or sporadic cases", "Tetrabenazine or deutetrabenazine, or atypical antipsychotics, for disabling chorea; treat depression and monitor suicide risk", "Multidisciplinary support, nutrition and swallowing assessment, genetic counseling for the family"],
 [S(10, 315, 316), B(23, 244, 245)], marker=structs("caudate-nucleus-l", "caudate-nucleus-r", "putamen-l", "putamen-r"), imagingHint=hint("coronal", 0, 10, 10, "caudate heads bulging into the frontal horns"), preset="anterior", **X))

E.append(syn("syn-kluver-bucy", "Klüver–Bucy syndrome", "infectious", ["amygdala", "gyrus-parahippocampal-uncus", "hippocampus", "lobe-temporal"], "bilateral",
 "After recovering from herpes simplex encephalitis, or with a frontotemporal dementia or bilateral temporal injury, a patient becomes strangely placid, examines every object by putting it in the mouth, eats indiscriminately including inedible things, makes inappropriate sexual advances, cannot recognize familiar people or objects by sight, and is compulsively drawn to touch and inspect whatever comes into view. Memory is often severely impaired as well.",
 [D("cognitive", "bilateral", "amygdala", "Placidity, loss of fear and aggression, blunted emotional response", "amygdala"), D("cognitive", "bilateral", "temporal-limbic", "Hyperorality, dietary changes and hyperphagia; hypersexuality", "gyrus-parahippocampal-uncus"), D("cognitive", "bilateral", "inferotemporal cortex", "Visual agnosia (psychic blindness) and hypermetamorphosis (compulsive attention to visual stimuli)", "lobe-temporal"), D("cognitive", "bilateral", "hippocampus", "Amnesia when the hippocampi are involved", "hippocampus")],
 "The amygdala attaches emotional and motivational value to what is perceived: it receives highly processed visual, auditory and gustatory information from the temporal cortex and returns outputs to the hypothalamus and brainstem that generate fear, aggression, feeding and sexual responses. When both amygdalae and the surrounding anterior temporal cortex are destroyed, objects are seen but stripped of their meaning and their emotional tag, so the patient shows no fear of things that should frighten, no disgust at things that should be avoided and no restraint in eating or sexual behavior, and returns to exploring the world by mouth and hand like an infant because visual recognition no longer suffices. The inferotemporal visual association cortex, adjacent to the amygdala, accounts for the visual agnosia, and the hippocampi, further back, for the amnesia. The syndrome requires bilateral lesions because each amygdala is connected with both hemispheres' association cortex and one is enough to sustain emotional evaluation; unilateral temporal lesions produce only subtle changes, and there is no ipsilateral or contralateral pattern. Herpes simplex encephalitis targets the medial temporal lobes bilaterally, which is why it is the commonest cause in adults; frontotemporal dementia, bilateral temporal trauma, hypoxia, Pick disease and bilateral temporal lobectomy are the others. The full syndrome as described in monkeys is rare in humans; partial forms with placidity and hyperorality are more common.",
 [pathol("Herpes simplex encephalitis", "MRI", "Bilateral, asymmetric T2/FLAIR hyperintensity and restricted diffusion in the medial temporal lobes, insula and cingulate, with hemorrhage and later cystic encephalomalacia of both anterior temporal lobes.", sequence="FLAIR"), pathol("Frontotemporal dementia", "MRI", "Bilateral anterior temporal atrophy, often asymmetric, with hypometabolism on FDG-PET.", sequence="T1"), pathol("Bilateral temporal injury", "CT", "Bilateral temporal contusions after trauma or hypoxic-ischemic injury of the hippocampi and amygdalae.", sequence="CT non-contrast")],
 ["Herpes simplex encephalitis", "Frontotemporal dementia (semantic variant) and Pick disease", "Bilateral temporal lobe trauma, hypoxia or surgery", "Limbic encephalitis (paraneoplastic or autoimmune)", "Late Alzheimer disease"],
 [("Frontal lobe disinhibition", "Disinhibition with intact recognition and without hyperorality or visual agnosia; orbitofrontal lesion"), ("Prosopagnosia", "Isolated failure to recognize faces from bilateral fusiform lesions, emotion intact"), ("Delirium", "Fluctuating attention with a metabolic cause")],
 ["Treat the underlying cause (acyclovir for herpes encephalitis)", "Behavioral management, supervision of eating and safety; selective serotonin reuptake inhibitors or carbamazepine may reduce hyperorality and hypersexuality", "Support for caregivers; the syndrome partially improves after encephalitis"],
 [S(9, 306)], marker=structs("amygdala-l", "amygdala-r", "uncus-l", "uncus-r"), imagingHint=hint("coronal", 0, -5, -20, "both amygdalae and unci"), preset="anterior", **X))

E.append(syn("syn-hypothalamic-syndromes", "Hypothalamic syndromes", "neoplastic", ["hypothalamus", "pituitary-infundibulum", "mammillary-body", "optic-chiasm"], "bilateral",
 "A child with a suprasellar tumor stops growing, drinks and passes enormous volumes of dilute urine, sleeps at odd hours and becomes either wasted or obese with an insatiable appetite. An adult with a lesion of the same region has a body temperature that swings without infection, faints on standing, has lost the ability to feel thirst and has become emotionally flat or explosively angry. Visual field loss from the neighboring chiasm and the endocrine failure of the pituitary are frequent companions.",
 [D("autonomic", "bilateral", "water balance", "Diabetes insipidus (supraoptic and paraventricular nuclei); adipsia or hypernatremia with anterior lesions; SIADH with irritative lesions", "hypothalamus"), D("autonomic", "bilateral", "temperature", "Hyperthermia with anterior (preoptic) lesions, hypothermia or poikilothermia with posterior lesions", "hypothalamus"), D("autonomic", "bilateral", "feeding", "Hyperphagia and obesity with ventromedial lesions; anorexia and emaciation (diencephalic syndrome of infancy) with lateral lesions", "hypothalamus"), D("consciousness", "bilateral", "sleep-wake", "Hypersomnia with posterior lesions, insomnia with anterior lesions; disrupted circadian rhythm (suprachiasmatic nucleus)", "reticular-formation"), D("other", "bilateral", "endocrine", "Hypopituitarism, growth failure, precocious or delayed puberty, hyperprolactinemia from stalk compression", "pituitary-infundibulum"), D("cognitive", "bilateral", "emotion and memory", "Rage, apathy, emotional lability; amnesia with mammillary body involvement", "mammillary-body")],
 "The hypothalamus is a few grams of tissue in the walls and floor of the third ventricle that regulates the internal environment through three routes: the pituitary, by releasing hormones into the portal vessels and by sending vasopressin and oxytocin down the stalk to the posterior lobe; the autonomic nervous system, through descending fibers to the brainstem and spinal preganglionic neurons; and behavior, through the limbic system. Its nuclei are arranged so that the anterior region houses the supraoptic and paraventricular nuclei that make vasopressin, the preoptic heat-loss center and the sleep-promoting neurons, while the posterior region contains the heat-conserving and arousal (orexin) neurons and the mammillary bodies of the memory circuit, and the medial tuberal region holds the ventromedial satiety and arcuate feeding nuclei beside the lateral feeding area. A lesion can therefore be localized by its combination of effects: anterior lesions cause hyperthermia, insomnia and diabetes insipidus, posterior lesions hypothermia, hypersomnia and amnesia, ventromedial lesions hyperphagia and rage, lateral lesions anorexia. Because the paired nuclei sit on either side of the narrow third ventricle and each projects bilaterally, most syndromes require bilateral or midline lesions and show no lateralization, with no ipsilateral or contralateral rule to apply, and the neighboring chiasm and pituitary stalk are almost always involved by the same mass, adding the bitemporal field defect and hypopituitarism. Craniopharyngiomas, hypothalamic gliomas, germinomas, sarcoidosis, Langerhans cell histiocytosis and surgery of the region are the usual causes.",
 [pathol("Hypothalamic or suprasellar mass", "MRI", "Craniopharyngioma (cystic, calcified), optic-hypothalamic glioma (T2-bright infiltrating mass), germinoma (enhancing, often with a pineal twin) or hamartoma of the tuber cinereum in the floor of the third ventricle; thickened enhancing stalk in histiocytosis, sarcoidosis and hypophysitis.", sequence="T1+Gd"), pathol("Loss of the posterior pituitary bright spot", "MRI", "Absent T1 hyperintensity of the neurohypophysis in central diabetes insipidus.", sequence="T1"), pathol("Wernicke encephalopathy and other symmetric lesions", "MRI", "Symmetric FLAIR change around the third ventricle and in the mammillary bodies.", sequence="FLAIR")],
 ["Craniopharyngioma", "Hypothalamic or optic pathway glioma (neurofibromatosis 1)", "Germ cell tumor", "Sarcoidosis, Langerhans cell histiocytosis, lymphocytic hypophysitis", "Surgery or radiotherapy of the region, subarachnoid hemorrhage, trauma", "Wernicke encephalopathy", "Hypothalamic hamartoma (gelastic seizures, precocious puberty)"],
 [("Primary endocrine disease", "Single hormone axis, no thirst, temperature or sleep disturbance"), ("Psychogenic polydipsia", "Water deprivation concentrates the urine; no lesion"), ("Pituitary adenoma", "Sellar origin, hypopituitarism and chiasmal compression without hypothalamic dysregulation until very large")],
 ["MRI of the sella and hypothalamus with contrast; full pituitary hormone profile, paired serum and urine osmolality; tumor markers and CSF cytology for germ cell tumors", "Replace deficient hormones, especially cortisol before thyroxine; desmopressin for diabetes insipidus with careful fluid balance in adipsic patients", "Treat the lesion (surgery, radiotherapy, chemotherapy) with an awareness that hypothalamic damage from treatment causes obesity and sleep disturbance"],
 [S(13, 382, 383), S(13, 373, 386)], marker=structs("hypothalamus-anterior-l", "hypothalamus-anterior-r", "hypothalamus-posterior-l", "hypothalamus-posterior-r"), imagingHint=hint("coronal", 0, -5, -12, "hypothalamus in the walls of the third ventricle"), preset="anterior", **X))

E.append(syn("syn-multiple-sclerosis-pattern", "Multiple sclerosis: the pattern of lesions in space and time", "demyelinating", ["cn-02-optic", "medial-longitudinal-fasciculus", "spinal-white-columns", "corpus-callosum", "corona-radiata", "cerebellum"], "bilateral",
 "A woman in her twenties had an episode of painful blurred vision in one eye three years ago that recovered; last year her legs became numb and stiff for a month; now she has double vision on looking to one side and a band of tingling around her chest, all worse after a hot bath. Examination shows a pale optic disc, an internuclear ophthalmoplegia, brisk reflexes with an extensor plantar, and reduced vibration sense at the ankles. Episodes separated in time and lesions separated in space, in a young adult, define the disease.",
 [D("visual-acuity", "ipsilateral", "one eye", "Optic neuritis: subacute monocular visual loss with pain on eye movement and an afferent pupillary defect; later optic atrophy", "cn-02-optic"), D("oculomotor", "ipsilateral", "adduction", "Internuclear ophthalmoplegia, often bilateral", "medial-longitudinal-fasciculus"), D("sensory-vibration-proprioception", "bilateral", "legs, trunk", "Partial myelitis: numbness, band-like tightness, Lhermitte sign, useless hand from posterior column lesions", "pathway-dcml"), D("motor", "bilateral", "legs more than arms", "Spastic paraparesis with hyperreflexia and extensor plantars; fatigue and Uhthoff phenomenon", "pathway-lateral-corticospinal"), D("cerebellar", "bilateral", "limbs and gait", "Ataxia, intention tremor, scanning speech", "pathway-cerebellar-circuits"), D("sphincter", "bilateral", "bladder", "Urgency, frequency, incomplete emptying", "intermediolateral-column"), D("cognitive", "bilateral", "diffuse", "Cognitive slowing, depression, fatigue", "corona-radiata")],
 "Multiple sclerosis is an immune attack on central myelin that produces focal plaques of demyelination wherever oligodendrocyte myelin lies, with a predilection for the periventricular white matter around the small veins, the corpus callosum, the optic nerves, the brainstem tegmentum around the fourth ventricle and aqueduct, the cerebellar peduncles and the dorsolateral spinal cord. Each plaque blocks or slows conduction in the fibers passing through it, and the symptoms of an attack are those of the pathway interrupted: a plaque in the optic nerve, a central nervous system tract, causes monocular visual loss with an afferent pupillary defect; a plaque in the MLF disconnects the abducens interneurons from the contralateral medial rectus after they have crossed, producing an internuclear ophthalmoplegia, bilateral when the paramedian plaque spans both bundles; a dorsolateral cord plaque interrupts the uncrossed posterior column and the crossed lateral corticospinal tract on one side, giving ipsilateral proprioceptive loss and spasticity below it, often without a complete level; and cerebellar peduncle plaques give ipsilateral ataxia. Because plaques are scattered and each attack strikes a different site, the deficits accumulate in a distribution that no single lesion could produce, the dissemination in space, and because inflammation subsides and conduction partially recovers through remyelination and sodium channel redistribution, attacks remit, the dissemination in time, until progressive axonal loss produces steadily worsening disability. Heat blocks marginal conduction in demyelinated fibers, explaining the worsening in hot baths and the transient Uhthoff phenomenon. MRI now demonstrates dissemination in space and time in a single scan, and CSF oligoclonal bands show the intrathecal immune response. Neuromyelitis optica, with its long cord lesions and severe optic neuritis, and MOG antibody disease are the diseases most easily confused with it and require different treatment.",
 [pathol("Demyelinating plaques", "MRI", "Ovoid T2/FLAIR-bright lesions perpendicular to the ventricles (Dawson fingers), in the corpus callosum, juxtacortical, infratentorial (pons, cerebellar peduncles) and spinal cord (short, eccentric, dorsolateral); central vein sign on SWI; hypointense 'black holes' on T1 for axonal loss.", sequence="FLAIR"), pathol("Active lesions", "MRI", "Gadolinium enhancement, often ring or open-ring, in lesions of the last few weeks; simultaneous enhancing and non-enhancing lesions demonstrate dissemination in time.", sequence="T1+Gd"), pathol("Intrathecal immunoglobulin synthesis", "LP/CSF", "Oligoclonal bands present in CSF but not serum in over 90% of established cases; mild lymphocytic pleocytosis.", sequence="n/a"), pathol("Optic neuritis", "MRI", "Short-segment enhancement of the optic nerve; delayed visual evoked potentials afterward.", sequence="T1+Gd")],
 ["Multiple sclerosis (relapsing-remitting, secondary progressive, primary progressive)", "Clinically isolated syndrome (first attack)", "Radiologically isolated syndrome"],
 [("Neuromyelitis optica spectrum disorder", "Longitudinally extensive myelitis, severe bilateral optic neuritis, area postrema syndrome; aquaporin-4 antibodies"), ("MOG antibody-associated disease", "Bilateral optic neuritis with disc swelling, ADEM-like attacks, good recovery; MOG antibodies"), ("Small vessel ischemic disease", "Older patient with vascular risk factors, subcortical lesions sparing the callosum, no bands"), ("Systemic lupus, sarcoidosis, Behçet, Susac syndrome, CNS lymphoma", "Systemic features, atypical imaging, different CSF"), ("Functional neurological disorder", "Inconsistent signs, normal imaging")],
 ["MRI of the brain and whole spine with contrast, lumbar puncture for oligoclonal bands, aquaporin-4 and MOG antibodies when atypical; apply the McDonald criteria for dissemination in space and time", "High-dose methylprednisolone for disabling relapses; early disease-modifying therapy (from interferons and glatiramer to natalizumab, ocrelizumab, ofatumumab, cladribine) chosen by activity and risk", "Symptomatic care: spasticity, bladder, fatigue, pain, depression; vitamin D, smoking cessation, exercise"],
 [B(21, 223, 228)], marker=structs("optic-nerve-l", "corpus-callosum", "brainstem"), imagingHint=hint("sagittal", -5, -20, 20, "periventricular white matter and callosum where plaques cluster"), preset="medial-l", eponyms=["disseminated sclerosis"], **X))

